// ── Batch write helper (25 items per batch, retries unprocessed) ──
async function batchPut(tableName: string, items: Record<string, unknown>[]) {
  const chunkSize = 25;
  for (let i = 0; i < items.length; i += chunkSize) {
    const chunk = items.slice(i, i + chunkSize);
    let retries = 0;
    let pending = chunk;
    while (pending.length > 0 && retries <= 3) {
      const result = await ddbClient.send(new BatchWriteCommand({
        RequestItems: { [tableName]: pending.map((item) => ({ PutRequest: { Item: item } })) },
      }));
      const unprocessed = result.UnprocessedItems?.[tableName];
      if (unprocessed && unprocessed.length > 0) {
        pending = unprocessed.map((u) => u.PutRequest!.Item as Record<string, unknown>);
        retries++;
        await new Promise((r) => setTimeout(r, 100 * Math.pow(2, retries)));
      } else {
        pending = [];
      }
    }
  }
}

// ── Seed all tables ──
export async function seedGlobalorTables(): Promise<void> {
  const tableOrder: (keyof typeof TABLES)[] = ["USERS","PROFILES","USER_ROLES","DEBTORS","VENDORS","SUPPLIERS","INVOICES","PURCHASE_INVOICES","PURCHASE_ORDERS","ADVANCES","EXPENSES","STOCK_MOVEMENTS","INVENTORY_ITEMS","ALERTS","CREDIT_DEBIT_NOTES","PAYMENTS","CHART_OF_ACCOUNTS","JOURNAL_ENTRIES","BALANCE_SHEET_ITEMS","COMPANIES","PRODUCTS","CATALOGUE_SETTINGS","GOODS_PURCHASE_ORDERS","GOODS_RECEIPTS","GOODS_SALES_ORDERS","GOODS_DISPATCHES","QUOTATIONS","FORECAST_VARIABLES","EMAIL_REGISTRY"];
  for (const key of tableOrder) {
    const items = SEED_DATA[key] ?? [];
    if (items.length === 0) {
      console.log(`   - ${key}: 0 items, skipping`);
      continue;
    }
    console.log(`   + ${key}: writing ${items.length} items...`);
    try {
      await batchPut(TABLES[key], items);
      console.log(`   OK ${key}: done`);
    } catch (err: any) {
      console.error(`   FAIL ${key}: ${err.message}`);
    }
  }
}

// Run directly: npx tsx src/globalor-seed-data.ts
if (process.argv[1]?.endsWith("globalor-seed-data.ts") || process.argv[1]?.endsWith("globalor-seed-data.js")) {
  seedGlobalorTables()
    .then(() => {
      console.log("\nSeed complete!");
      process.exit(0);
    })
    .catch((err) => {
      console.error("\nSeed failed:", err);
      process.exit(1);
    });
}
